#include "web_admin.h"

#include <WiFi.h>
#include <ESPAsyncWebServer.h>
#include <DNSServer.h>

#include "beacon_config.h"
#include "web_assets.h"  // generated by tools/compress.py

// External config lives on the main-loop task. Async handlers must use
// readWebSnapshot() instead of touching it directly (see handleGetConfig).
extern BeaconConfig config;
extern void updateWebSnapshot();

static AsyncWebServer server(80);
static DNSServer dnsServer;
static bool running = false;
static String apSsid;
static String apIp = "10.0.0.8";

static uint32_t lastActivityMs = 0;

static String stateName(int s) {
  switch (s) {
    case 0: return "StartupDelay";
    case 1: return "Idle";
    case 2: return "Transmitting";
    case 3: return "ContinuousTransmit";
    case 4: return "LowBatteryHalt";
    default: return "Unknown";
  }
}

static void markActivity() {
  lastActivityMs = millis();
}

// --- Async request handlers ---

static void handleRoot(AsyncWebServerRequest *request) {
  markActivity();
  AsyncWebServerResponse *response = request->beginResponse(
      200, "text/html", INDEX_HTML, INDEX_HTML_LEN);
  response->addHeader("Content-Encoding", "gzip");
  response->addHeader("Cache-Control", "no-store");
  request->send(response);
}

static void handleStyle(AsyncWebServerRequest *request) {
  markActivity();
  AsyncWebServerResponse *response = request->beginResponse(
      200, "text/css", STYLE_CSS, STYLE_CSS_LEN);
  response->addHeader("Content-Encoding", "gzip");
  response->addHeader("Cache-Control", "max-age=3600");
  request->send(response);
}

static void handleScript(AsyncWebServerRequest *request) {
  markActivity();
  AsyncWebServerResponse *response = request->beginResponse(
      200, "text/javascript", SCRIPT_JS, SCRIPT_JS_LEN);
  response->addHeader("Content-Encoding", "gzip");
  response->addHeader("Cache-Control", "max-age=3600");
  request->send(response);
}

static void handleGetConfig(AsyncWebServerRequest *request) {
  markActivity();
  // Read-only snapshot copied under lock. No direct config access here:
  // config lives on the main-loop task and may be rewritten at any time.
  WebSnapshot s;
  readWebSnapshot(&s);
  static char json[1024];
  int n;
  if (s.hasBatteryPct) {
    n = snprintf(json, sizeof(json),
      "{\"call\":\"%s\",\"fox\":\"%s\",\"beaconMode\":%s,\"foxSync\":%s,"
      "\"foxNum\":%u,\"startup\":%lu,\"startupResolved\":%lu,\"tx\":%lu,\"idle\":%lu,"
      "\"beaconId\":%u,\"wpm\":%u,\"tone\":%u,\"warble\":%s,"
      "\"warbleLow\":%u,\"warbleHigh\":%u,\"warbleStep\":%u,"
      "\"pttActiveLow\":%s,\"lead\":%u,\"tail\":%u,"
      "\"batteryEnabled\":%s,\"batteryScale\":%.3f,\"lowBattery\":%.2f,"
      "\"wifiAp\":%s,\"wifiApTimeout\":%u,\"ecoMode\":%s,"
      "\"state\":\"%s\",\"battery\":\"%s\",\"batteryPct\":%s,"
      "\"apSsid\":\"%s\",\"ip\":\"%s\",\"wifiPwSet\":%s,\"overlap\":%s}",
      s.call, s.fox,
      s.beaconMode ? "true" : "false",
      s.foxSync ? "true" : "false",
      (unsigned)s.foxNum,
      (unsigned long)s.startup,
      (unsigned long)s.startupResolved,
      (unsigned long)s.tx,
      (unsigned long)s.idle,
      s.beaconId, s.wpm, s.tone,
      s.warble ? "true" : "false",
      s.warbleLow, s.warbleHigh, s.warbleStep,
      s.pttActiveLow ? "true" : "false",
      s.lead, s.tail,
      s.batteryEnabled ? "true" : "false",
      s.batteryScale, s.lowBattery,
      s.wifiAp ? "true" : "false",
      s.wifiApTimeout,
      s.ecoMode ? "true" : "false",
      stateName(s.state), s.batteryStr, s.batteryPctStr,
      s.apSsid, s.ip,
      s.wifiPwSet ? "true" : "false",
      s.overlap ? "true" : "false");
  } else {
    n = snprintf(json, sizeof(json),
      "{\"call\":\"%s\",\"fox\":\"%s\",\"beaconMode\":%s,\"foxSync\":%s,"
      "\"foxNum\":%u,\"startup\":%lu,\"startupResolved\":%lu,\"tx\":%lu,\"idle\":%lu,"
      "\"beaconId\":%u,\"wpm\":%u,\"tone\":%u,\"warble\":%s,"
      "\"warbleLow\":%u,\"warbleHigh\":%u,\"warbleStep\":%u,"
      "\"pttActiveLow\":%s,\"lead\":%u,\"tail\":%u,"
      "\"batteryEnabled\":%s,\"batteryScale\":%.3f,\"lowBattery\":%.2f,"
      "\"wifiAp\":%s,\"wifiApTimeout\":%u,\"ecoMode\":%s,"
      "\"state\":\"%s\",\"battery\":\"%s\","
      "\"apSsid\":\"%s\",\"ip\":\"%s\",\"wifiPwSet\":%s,\"overlap\":%s}",
      s.call, s.fox,
      s.beaconMode ? "true" : "false",
      s.foxSync ? "true" : "false",
      (unsigned)s.foxNum,
      (unsigned long)s.startup,
      (unsigned long)s.startupResolved,
      (unsigned long)s.tx,
      (unsigned long)s.idle,
      s.beaconId, s.wpm, s.tone,
      s.warble ? "true" : "false",
      s.warbleLow, s.warbleHigh, s.warbleStep,
      s.pttActiveLow ? "true" : "false",
      s.lead, s.tail,
      s.batteryEnabled ? "true" : "false",
      s.batteryScale, s.lowBattery,
      s.wifiAp ? "true" : "false",
      s.wifiApTimeout,
      s.ecoMode ? "true" : "false",
      stateName(s.state), s.batteryStr,
      s.apSsid, s.ip,
      s.wifiPwSet ? "true" : "false",
      s.overlap ? "true" : "false");
  }
  if (n < 0 || n >= (int)sizeof(json)) {
    request->send(500, "text/plain", "Config too large");
    return;
  }
  request->send(200, "application/json", json);
}

static void copyParam(AsyncWebServerRequest *request, const char *name,
                      char *dst, size_t dstSize) {
  dst[0] = '\0';
  if (!request->hasParam(name, true)) return;
  String v = request->getParam(name, true)->value();
  v.trim();
  strncpy(dst, v.c_str(), dstSize - 1);
  dst[dstSize - 1] = '\0';
}

static void handlePostConfig(AsyncWebServerRequest *request) {
  markActivity();
  if (!request->hasParam("call", true)) {
    request->send(400, "text/plain", "Missing form data");
    return;
  }

  PendingConfig p;
  memset(&p, 0, sizeof(p));
  auto num = [&](const char *name) -> long {
    if (!request->hasParam(name, true)) return -1;
    return request->getParam(name, true)->value().toInt();
  };
  auto fnum = [&](const char *name) -> float {
    if (!request->hasParam(name, true)) return -1.0f;
    return request->getParam(name, true)->value().toFloat();
  };

  copyParam(request, "call", p.call, sizeof(p.call));
  copyParam(request, "fox", p.fox, sizeof(p.fox));
  copyParam(request, "mode", p.mode, sizeof(p.mode));
  copyParam(request, "fox_sync", p.foxSync, sizeof(p.foxSync));
  copyParam(request, "ptt", p.ptt, sizeof(p.ptt));
  copyParam(request, "warble", p.warble, sizeof(p.warble));
  copyParam(request, "battery", p.battery, sizeof(p.battery));
  copyParam(request, "wifi_ap", p.wifiAp, sizeof(p.wifiAp));
  copyParam(request, "eco_mode", p.ecoMode, sizeof(p.ecoMode));
  if (request->hasParam("wifi_password", true)) {
    copyParam(request, "wifi_password", p.wifiPassword, sizeof(p.wifiPassword));
    p.hasWifiPassword = true;
  }

  p.startup = num("startup");
  p.tx = num("tx");
  p.idle = num("idle");
  p.beaconId = num("beacon_id");
  p.wpm = num("wpm");
  p.tone = num("tone");
  p.warbleLow = num("warble_low");
  p.warbleHigh = num("warble_high");
  p.warbleStep = num("warble_step");
  p.lead = num("lead");
  p.tail = num("tail");
  p.wifiApTimeout = num("wifi_ap_timeout");
  p.batteryScale = fnum("battery_scale");
  p.lowBattery = fnum("low_battery");

  queueWebConfig(p);
  request->send(200, "text/plain", "Saved. Applying on main loop.");
}

static void handleTest(AsyncWebServerRequest *request) {
  markActivity();
  queueWebTest();
  request->send(200, "text/plain", "Test transmission queued.");
}

static void handlePttTest(AsyncWebServerRequest *request) {
  markActivity();
  queueWebPtt();
  request->send(200, "text/plain", "PTT test queued. Runs when radio is idle.");
}

static void handleDefaults(AsyncWebServerRequest *request) {
  markActivity();
  queueWebDefaults();
  request->send(200, "text/plain", "Defaults queued. Reboot recommended.");
}

static void handleReboot(AsyncWebServerRequest *request) {
  markActivity();
  queueWebReboot();
  request->send(200, "text/plain", "Reboot queued. Radio will be safed first.");
}

static void handleNotFound(AsyncWebServerRequest *request) {
  markActivity();
  String url = request->url();
  if (url.startsWith("/api/")) {
    request->send(404, "text/plain", "Not found");
    return;
  }
  // Captive portal: redirect all unknown page URLs to root.
  request->redirect("http://10.0.0.8/");
}

// --- Public API ---

void webAdminInit(const char *apNamePrefix) {
  if (running) return;
  uint64_t mac = ESP.getEfuseMac();
  char macSuffix[5];
  snprintf(macSuffix, sizeof(macSuffix), "%02X%02X",
           (uint8_t)(mac >> 8), (uint8_t)mac);
  apSsid = String(apNamePrefix) + "-" + macSuffix;

  WiFi.mode(WIFI_AP);
  WiFi.softAPConfig(IPAddress(10, 0, 0, 8), IPAddress(10, 0, 0, 8), IPAddress(255, 255, 255, 0));
  if (strlen(config.wifiApPassword) >= 8) {
    WiFi.softAP(apSsid.c_str(), config.wifiApPassword);
  } else {
    WiFi.softAP(apSsid.c_str());
  }
  apIp = WiFi.softAPIP().toString();

  // Captive portal DNS: redirect all queries to our IP.
  dnsServer.start(53, "*", WiFi.softAPIP());

  server.on("/", HTTP_GET, handleRoot);
  server.on("/style.css", HTTP_GET, handleStyle);
  server.on("/script.js", HTTP_GET, handleScript);
  server.on("/api/config", HTTP_GET, handleGetConfig);
  server.on("/api/config", HTTP_POST, handlePostConfig);
  server.on("/api/test", HTTP_POST, handleTest);
  server.on("/api/ptt_test", HTTP_POST, handlePttTest);
  server.on("/api/defaults", HTTP_POST, handleDefaults);
  server.on("/api/reboot", HTTP_POST, handleReboot);
  server.onNotFound(handleNotFound);
  server.begin();

  running = true;
  lastActivityMs = millis();
  Serial.printf("9M2PJU Fox Hunt Beacon — Web admin AP: %s, IP: %s\n", apSsid.c_str(), apIp.c_str());
}

void webAdminLoop() {
  if (!running) return;

  // Process captive portal DNS requests.
  dnsServer.processNextRequest();

  // Track station connections as activity.
  if (WiFi.softAPgetStationNum() > 0) {
    markActivity();
  }

  // Auto-off AP after timeout with no activity.
  if (config.wifiApTimeoutMinutes > 0) {
    uint32_t timeoutMs = (uint32_t)config.wifiApTimeoutMinutes * 60UL * 1000UL;
    if (millis() - lastActivityMs >= timeoutMs) {
      Serial.printf("WiFi AP auto-off after %u minutes of inactivity.\n",
                    config.wifiApTimeoutMinutes);
      config.wifiApEnabled = false;
      webAdminStop();
      updateWebSnapshot();
    }
  }
}

void webAdminStop() {
  if (!running) return;
  server.end();
  dnsServer.stop();
  WiFi.softAPdisconnect(true);
  WiFi.mode(WIFI_OFF);
  running = false;
  Serial.println(F("Web admin AP stopped."));
}

String webAdminGetIp() {
  return apIp;
}

String webAdminGetSsid() {
  return apSsid;
}

bool webAdminIsRunning() {
  return running;
}
